from typing import List

class Solution:
    def findPeakElement(self, nums: List[int]) -> int:
        n = len(nums)
        for i in range(n):
            left = float("-inf") if i == 0 else nums[i - 1]
            right = float("-inf") if i == n - 1 else nums[i + 1]
            if nums[i] > left and nums[i] > right:
                return i
        return 0

